//go:build arm64

package floats

// The NEON kernel of AllPass3 (allpass.go), generated by go-asmgen (allpass_arm64_gen.go)
// into allpass_arm64.s: one row per 128-bit register. NEON is the ARMv8-A baseline: no
// gate. The caller guarantees n >= 1 and the lengths of every operand. Every operand is
// passed as a pointer to its first element. No kernel keeps a pointer: go:noescape.
//
//go:noescape
func allPass3NEON(n int, out, in, phi, q0, q1, q2 *complex128, c0, c1, c2 *float64, old0, new0, old1, new1, old2, new2 *complex128)

func allPass3(n int, out, in []complex128, t *AllPassRows, old, cur *[3][]complex128) {
	allPass3NEON(n, &out[0], &in[0], &t.Phi[0], &t.Q0[0], &t.Q1[0], &t.Q2[0], &t.C0[0], &t.C1[0], &t.C2[0],
		&old[0][0], &cur[0][0], &old[1][0], &cur[1][0], &old[2][0], &cur[2][0])
}
